package com.jfeatures.msg.customer.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import jakarta.servlet.http.HttpServletRequest;
import java.lang.Exception;
import java.lang.String;

/**
 * Utility class for extracting authenticated user identity from HTTP requests.
 * Supports JWT token extraction (primary method) and HTTP header fallback.
 * Generated by MSG - Microservice Generator.
 */
public class AuthenticationUtil {
  /**
   * Extract user ID from HTTP request.
   * Tries JWT token extraction first, falls back to X-User-Id header.
   * @param request HTTP servlet request
   * @return User ID string, or "system" if not found
   */
  public static String getUserId(HttpServletRequest request) {
    String authHeader = request.getHeader("Authorization");

    if (authHeader != null && authHeader.startsWith("Bearer ")) {
      String token = authHeader.substring(7);
      String userIdFromJwt = extractUserIdFromJwt(token);
      if (userIdFromJwt != null) {
        return userIdFromJwt;
      }
    }

    return extractUserIdFromHeader(request);
  }

  /**
   * Extract user ID from JWT token claims.
   * Tries multiple common claim names: userId, sub, user_id.
   * @param token JWT token string
   * @return User ID if found, null otherwise
   */
  private static String extractUserIdFromJwt(String token) {
    try {
      // Parse JWT token without signature verification (for demo/dev purposes)
      // In production, use proper secret key: Jwts.parserBuilder().setSigningKey(key).build()
      int lastDotIndex = token.lastIndexOf('.');
      if (lastDotIndex > 0) {
        String tokenWithoutSignature = token.substring(0, lastDotIndex + 1);
        Claims claims = Jwts.parserBuilder().build().parseClaimsJwt(tokenWithoutSignature).getBody();

        // Try common claim names for user ID
        String userId = claims.get("userId", String.class);
        if (userId != null) {
          return userId;
        }

        userId = claims.get("sub", String.class);
        if (userId != null) {
          return userId;
        }

        userId = claims.get("user_id", String.class);
        if (userId != null) {
          return userId;
        }
      }
    } catch (Exception e) {
      // JWT parsing failed, return null to try fallback methods
      return null;
    }

    return null;
  }

  /**
   * Extract user ID from X-User-Id HTTP header (fallback method).
   * @param request HTTP servlet request
   * @return User ID from header, or "system" as default
   */
  private static String extractUserIdFromHeader(HttpServletRequest request) {
    String userId = request.getHeader("X-User-Id");
    if (userId != null && !userId.trim().isEmpty()) {
      return userId.trim();
    }

    // Default to 'system' if no user identification found
    return "system";
  }
}
